module tb_record_flags;
 import cut_types::*;
 logic[4:0] op; logic wr,ov,so; logic[$bits(iu_ctrl_t)-1:0] ctrl;
 logic[31:0] a,b; wire issue_packet_t held;
 assign held={ctrl,a,b};
 logic[32:0] add_sum;logic add_overflow,final_so;
 logic[63:0] multiply_acc;logic[31:0] divider_quotient;logic[5:0] leading_zeros;
 logic record_a_sign,record_a_nonzero,record_b_sign,record_b_nonzero;
 wire[31:0] rv_old[2],rv_new[2];wire[3:0] cr_old[2],cr_new[2];
 for(genvar g=0;g<2;g++)begin:p
 record_old #(.ADD_COMPARE_ONLY(g!=0)) x(.*,.record_value(rv_old[g]),.cr0(cr_old[g]));
 record_new #(.ADD_COMPARE_ONLY(g!=0)) y(.*,.record_value(rv_new[g]),.cr0(cr_new[g]));
 end
 function automatic logic q(input integer x);
 case(x&3)0:q=0;1:q=1;2:q=1'bx;default:q=1'bz;endcase
 endfunction
 function automatic logic[31:0] data(input integer x);
 case(x&15)
 0:data=0;1:data='1;2:data=32'h80000000;3:data=1;
 4:data=32'h7fffffff;5:data=32'haaaa5555;6:data='x;7:data='z;
 8:data=32'h0000xxxx;9:data=32'hxxxx0000;10:data=32'hzzzz0000;
 11:data=32'h0000zzzz;12:data={1'bx,31'b0};13:data={1'bz,31'h7fffffff};
 14:data=32'h0000000x;default:data=32'hfffffffx;
 endcase
 endfunction
 integer checks=0,unknown_op=0,invalid_op=0,wr_xz=0;integer each_op[32];
 initial begin
 for(integer k=0;k<32;k++)each_op[k]=0;
 for(integer o=0;o<1024;o++)begin
  for(integer k=0;k<5;k++)op[k]=q(o>>(2*k));
  for(integer v=0;v<256;v++)begin
   wr=q(v);ov=q(v>>2);so=q(v>>4);final_so=q(v>>6);
   ctrl={op,{($bits(iu_ctrl_t)-5){1'b0}}};
   ctrl[CQ_INDEX_WIDTH+CQ_GENERATION_WIDTH]=wr;
   ctrl[CQ_INDEX_WIDTH+CQ_GENERATION_WIDTH+1]=ov;
   ctrl[CQ_INDEX_WIDTH+CQ_GENERATION_WIDTH+3]=so;
   a=data(v);b=data(v>>2);add_sum={q(v>>2),data(v+3)};
   add_overflow=q(v>>4);multiply_acc={data(v+7),data(v+9)};
   divider_quotient=data(v+11);leading_zeros=6'(v);
   if((v&15)==6)leading_zeros='x;
   if((v&15)==7)leading_zeros='z;
   record_a_sign=q(v);record_a_nonzero=q(v>>2);
   record_b_sign=q(v>>4);record_b_nonzero=q(v>>6);
   #1;
   for(integer p=0;p<2;p++)begin
    if((p==1 && rv_old[p]!==rv_new[p])||cr_old[p]!==cr_new[p])$fatal(1,"record mismatch op=%b data=%0d profile=%0d old=%b new=%b",op,v,p,cr_old[p],cr_new[p]);
    checks++;
   end
   if($isunknown(op))unknown_op++;else begin each_op[op]++;if(op>=25)invalid_op++;end
   if($isunknown(wr))wr_xz++;
  end
 end
 if(checks!=524288||unknown_op==0||invalid_op==0||wr_xz==0)$fatal(1,"coverage incomplete");
 for(integer k=0;k<32;k++)if(each_op[k]!=256)$fatal(1,"opcode bin missing");
 $display("PASS record flags comparisons=%0d unknownOp=%0d invalidOp=%0d unknownWrite=%0d",checks,unknown_op,invalid_op,wr_xz);
 $finish;
 end
endmodule
